<?php $entry = $args['entry'] ?? null; ?>
<article class="wrap arcsecs-reader arcsecs-library-reader" aria-labelledby="library-reader-title">
    <nav class="arcsecs-library-breadcrumb" aria-label="Breadcrumb"><a href="<?php echo esc_url( arcsecs_ai_access_url( 'research-library/' ) ); ?>">Research Library</a><?php if ( $entry ) : ?> <span aria-hidden="true">/</span> <span><?php echo esc_html( 'report' === $entry['kind'] ? sprintf( 'R%02d', $entry['number'] ) : $entry['title'] ); ?></span><?php endif; ?></nav>
    <?php if ( ! $entry ) : ?><header class="arcsecs-reader-intro"><h1 id="library-reader-title">Research page not found</h1><p>Return to the scientific archive to choose an available document.</p><a class="arcsecs-button" href="<?php echo esc_url( arcsecs_ai_access_url( 'research-library/' ) ); ?>">Browse the library</a></header><?php else : ?>
    <header class="arcsecs-reader-intro">
        <div class="eyebrow"><?php echo esc_html( 'report' === $entry['kind'] ? sprintf( 'R%02d · Historical working research', $entry['number'] ) : 'ArcSecs · Scientific Research Library' ); ?></div>
        <h1 id="library-reader-title"><?php echo esc_html( $entry['title'] ); ?></h1><p><?php echo esc_html( $entry['description'] ); ?></p>
        <?php if ( 'report' === $entry['kind'] || 'review' === $entry['kind'] ) : ?><p class="arcsecs-pub-boundary"><strong>Read in context:</strong> This is an archival scientific research document, not a claim of peer review or empirical proof. Older terminology and premises remain in the historical record. See the <a href="<?php echo esc_url( arcsecs_ai_access_url( 'research-library/foundations/' ) ); ?>">current twelve foundations</a> and <a href="<?php echo esc_url( arcsecs_ai_access_url( 'research-library/evidence-guide/' ) ); ?>">evidence guide</a>.</p><?php endif; ?>
        <div class="arcsecs-pub-actions">
            <?php if ( isset( $entry['download_sha256'] ) ) : ?><a class="arcsecs-button" href="<?php echo esc_url( arcsecs_library_asset_url( $entry['slug'] . '/source.md' ) ); ?>" download>Download source Markdown</a><?php endif; ?>
            <?php if ( isset( $entry['reader_route'] ) ) : ?><a class="arcsecs-button" href="<?php echo esc_url( arcsecs_ai_access_url( $entry['reader_route'] ) ); ?>">Read the complete Review 6.0</a><?php endif; ?>
            <?php if ( isset( $entry['pdf_url'] ) ) : ?><a class="arcsecs-button ghost" href="<?php echo esc_url( $entry['pdf_url'] ); ?>">Original PDF on GitHub</a><?php endif; ?>
            <?php if ( isset( $entry['source_url'] ) ) : ?><a class="arcsecs-button ghost" href="<?php echo esc_url( $entry['source_url'] ); ?>">Pinned original source</a><?php endif; ?>
            <a class="arcsecs-button ghost" href="<?php echo esc_url( arcsecs_ai_access_url( 'ai-corpus/' ) ); ?>">AI corpus</a>
        </div>
        <?php if ( isset( $entry['source_sha256'] ) ) : ?><details class="arcsecs-library-provenance"><summary>Source provenance and reuse</summary><p>Source: <code><?php echo esc_html( $entry['source_path'] ); ?></code></p><p>Original SHA-256: <code><?php echo esc_html( $entry['source_sha256'] ); ?></code></p><?php if ( isset( $entry['download_sha256'] ) ) : ?><p>Download SHA-256: <code><?php echo esc_html( $entry['download_sha256'] ); ?></code></p><?php endif; ?><p>Original rights-controlled materials: CC0 1.0; third-party rights and existing software licenses remain. Cite the exact version/source if useful. <a href="https://github.com/MichaelKappel/ArcSecs.com/blob/main/LICENSE.md">License scope</a>.</p><?php if ( ! empty( $entry['derivative_note'] ) ) : ?><p><?php echo esc_html( $entry['derivative_note'] ); ?></p><?php endif; ?></details><?php endif; ?>
        <?php if ( ! empty( $entry['math_fallbacks'] ) ) : ?><p class="arcsecs-pub-muted">Rendering notice: <?php echo esc_html( $entry['math_fallbacks'] ); ?> TeX conversion warnings were recorded. Consult the original Markdown/PDF for exact notation. Historical figure names are resolved from the shared Review 6 archive where necessary; use the original edition for exact figure context.</p><?php endif; ?>
    </header>
    <?php if ( 'reproducibility' === $entry['kind'] ) : get_template_part( 'template-parts/research-library-reproducibility' ); elseif ( isset( $entry['reader_route'] ) ) : ?>
        <section class="arcsecs-pub-section"><h2>Current scientific manuscript</h2><p>The full 129-page Review 6.0 is maintained in the existing dedicated reader. The original PDF and editable Markdown are freely available from the <a href="<?php echo esc_url( arcsecs_ai_access_url( 'publications/' ) ); ?>">publication catalog</a>. The related <a href="https://zenodo.org/records/24543781">Zenodo record</a> is linked as supplied; consult it for its registered metadata.</p><a class="arcsecs-button" href="<?php echo esc_url( arcsecs_ai_access_url( $entry['reader_route'] ) ); ?>">Open Review 6.0 reader</a></section>
    <?php elseif ( isset( $entry['html_sha256'] ) ) : ?>
        <?php if ( ! empty( $entry['headings'] ) ) : ?><details class="arcsecs-reader-toc"><summary>Contents · <?php echo esc_html( count( $entry['headings'] ) ); ?> section links</summary><nav aria-label="Document contents"><ol><?php foreach ( $entry['headings'] as $h ) : ?><li class="arcsecs-library-toc-level-<?php echo esc_attr( $h['level'] ); ?>"><a href="#<?php echo esc_attr( $h['id'] ); ?>"><?php echo esc_html( $h['title'] ); ?></a></li><?php endforeach; ?></ol></nav></details><?php endif; ?>
        <div class="arcsecs-reader-body arcsecs-library-body" id="library-document-body"><?php
        // Fixed manifest path; prebuilt, sanitized local HTML, never request-supplied markup.
        echo str_replace( array( '__ARCSECS_LIBRARY_ASSETS__', '__ARCSECS_LIBRARY_SITE__' ), array( esc_url( untrailingslashit( arcsecs_library_asset_url( '' ) ) ), esc_url( untrailingslashit( arcsecs_ai_access_url( '' ) ) ) ), file_get_contents( get_template_directory() . '/assets/research-library/' . $entry['slug'] . '/body.html' ) );
        ?></div>
        <p class="arcsecs-pub-muted">Reading derivative. Source links are preserved where resolvable; missing or external figures are indicated rather than fetched automatically. Historical bibliographic claims and external links are not newly verified.</p>
    <?php endif; ?>
    <?php if ( 'report' === $entry['kind'] ) : ?><nav class="arcsecs-library-pagination" aria-label="Adjacent reports"><?php if ( $entry['number'] > 1 ) : ?><a href="<?php echo esc_url( arcsecs_ai_access_url( 'research-library/reports/r' . sprintf( '%02d', $entry['number'] - 1 ) . '/' ) ); ?>">← Previous report</a><?php endif; ?><a href="<?php echo esc_url( arcsecs_ai_access_url( 'research-library/#library-reports' ) ); ?>">All reports</a><?php if ( $entry['number'] < 41 ) : ?><a href="<?php echo esc_url( arcsecs_ai_access_url( 'research-library/reports/r' . sprintf( '%02d', $entry['number'] + 1 ) . '/' ) ); ?>">Next report →</a><?php endif; ?></nav><?php endif; ?>
    <p><a href="<?php echo esc_url( arcsecs_ai_access_url( 'research-library/' ) ); ?>">Return to the Scientific Research Library</a> · <a href="<?php echo esc_url( arcsecs_ai_access_url( 'publications/' ) ); ?>">Book and paper</a></p>
    <?php endif; ?>
</article>
